import sys, json, random
sys.path.insert(0,'/workspace/fuzz'); sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/.deps')
import gen
from run_fuzz import subproc

# adversarial magnitude case: max alpha, rho=1, big demands, thin caps, deliver+step chains
def build():
    cases = []
    for ci in range(6):
        edges = [[i % 8, (i + 1) % 8, 1 if i % 3 else 1000] for i in range(64)]
        coms = []
        for k in range(24):
            s, t = k % 8, (k + 3) % 8
            paths = []
            used = set()
            for _ in range(8):
                # simple 1-2 edge walks
                for e in range(64):
                    if edges[e][0] == s:
                        p = [e]
                        if edges[e][1] != t:
                            for e2 in range(64):
                                if edges[e2][0] == edges[e][1] and edges[e2][1] == t:
                                    p = [e, e2]; break
                            else:
                                continue
                        if tuple(p) not in used:
                            used.add(tuple(p)); paths.append(p)
                            break
                else:
                    paths.append(None)
            coms.append({'source': s, 'sink': t, 'demand': 1000, 'paths': paths})
        workers = [[k for k in range(24) if k % 8 == w] for w in range(8)]
        ev = []
        tid = 0
        for rnd in range(30):
            for w in range(8):
                tid += 1
                ev.append({'op': 'issue', 'id': tid, 'worker': w})
                ev.append({'op': 'deliver', 'id': tid})
            ev.append({'op': 'step'})
            if len(ev) > 250: break
        cases.append({'nodes': 8, 'edges': edges, 'commodities': coms, 'workers': workers,
                      'quorum': 8, 'max_lag': 12, 'relax': [15, 8], 'rho': 1,
                      'mode': 'route', 'events': ev[:256]})
    req = {'cases': cases}
    return req

req = build()
raw = json.dumps(req, separators=(',',':')).encode()
print('bytes', len(raw))
res = subproc(raw)
mx = 0
def walk(o):
    global mx
    if isinstance(o, list):
        for v in o: walk(v)
    elif isinstance(o, dict):
        for v in o.values(): walk(v)
    elif isinstance(o, float):
        mx = max(mx, abs(o))
walk(res)
print('max |float| =', mx)
import verify
verify.verify_response(req, res)
print('verified OK')
EOF
